changeSet.sql:
CREATE EXTENSION IF NOT EXISTS btree_gist;

ALTER TABLE activity
    ADD CONSTRAINT ck_activity_time_range CHECK (end_time > start_time);

ALTER TABLE activity
    ADD CONSTRAINT ex_activity_hall_time
    EXCLUDE USING gist (
        hall_id WITH =,
        tsrange(date + start_time, date + end_time, '[)') WITH &&
    );

ALTER TABLE offer
    ADD CONSTRAINT ck_offer_positive_price CHECK (price > 0),
    ADD CONSTRAINT uq_offer_activity_type UNIQUE (activity_id, type);

rollback.sql:
ALTER TABLE offer DROP CONSTRAINT IF EXISTS uq_offer_activity_type;
ALTER TABLE offer DROP CONSTRAINT IF EXISTS ck_offer_positive_price;
ALTER TABLE activity DROP CONSTRAINT IF EXISTS ex_activity_hall_time;
ALTER TABLE activity DROP CONSTRAINT IF EXISTS ck_activity_time_range;
